mapper.sql:
from corporate_customer c left join corporate_rating r on r.active_customer_no = c.customer_no left join corporate_credit_limit l on l.active_customer_no = c.customer_no left join ( select customer_no_snapshot as customer_no, count(*) as application_count, sum(apply_amount) as application_amount_total from corporate_credit_application where deleted_flag = 0 group by customer_no_snapshot ) app on app.customer_no = c.customer_no left join ( select customer_no_snapshot as customer_no, count(*) as contract_count, sum(contract_amount) as contract_amount_total from corporate_credit_contract where deleted_flag = 0 group by customer_no_snapshot ) ct on ct.customer_no = c.customer_no left join ( select customer_no_snapshot as customer_no, count(*) as drawdown_count, sum(actual_draw_amount) as actual_draw_amount_total, sum(outstanding_principal_amount) as outstanding_principal_amount_total from corporate_credit_drawdown where deleted_flag = 0 group by customer_no_snapshot ) dr on dr.customer_no = c.customer_no left join ( select customer_no, count(*) as collateral_count, sum(confirmed_value) as confirmed_value_total from corporate_credit_collateral where deleted_flag = 0 group by customer_no ) co on co.customer_no = c.customer_no left join ( select customer_no, count(*) as contract_collateral_count, sum(secured_amount) as total_secured_amount from corporate_credit_contract_collateral where deleted_flag = 0 and relation_status = 'ACTIVE' group by customer_no ) rel on rel.customer_no = c.customer_no left join ( select customer_no, count(*) as exposure_count, sum(ead_amount) as ead_amount_total, sum(el_avg) as el_avg_total, max(pd) as max_pd from corporate_risk_exposure where deleted_flag = 0 group by customer_no ) ex on ex.customer_no = c.customer_no left join ( select customer_no, count(*) as overdue_count, max(overdue_days) as max_overdue_days, sum(total_overdue_amount) as overdue_amount_total from corporate_credit_overdue where deleted_flag = 0 group by customer_no ) ov on ov.customer_no = c.customer_no left join ( select customer_no, count(*) as debt_default_count, sum(default_exposure_amount) as default_exposure_amount_total, min(case default_level when 'A' then 1 when 'B' then 2 when 'C' then 3 else 9 end) as highest_default_rank from corporate_debt_default where deleted_flag = 0 group by customer_no ) dd on dd.customer_no = c.customer_no left join corporate_customer_default cd on cd.active_customer_no = c.customer_no where c.deleted_flag = 0
and ( c.customer_no like concat('%', #{criteria.keyword}, '%') or c.customer_name like concat('%', #{criteria.keyword}, '%') or ifnull(c.unified_social_credit_code, '') like concat('%', #{criteria.keyword}, '%') or ifnull(r.rating_no, '') like concat('%', #{criteria.keyword}, '%') or ifnull(l.limit_no, '') like concat('%', #{criteria.keyword}, '%') )
and c.customer_no like concat('%', #{criteria.customerNo}, '%')
and r.rating_level = #{criteria.ratingLevel}
and (c.risk_level = #{criteria.riskLevel} or ifnull(l.risk_level, '') = #{criteria.riskLevel})
and ( exists (select 1 from corporate_credit_application x where x.customer_no_snapshot = c.customer_no and x.deleted_flag = 0 and x.product_type like concat('%', #{criteria.productType}, '%')) or exists (select 1 from corporate_credit_contract x where x.customer_no_snapshot = c.customer_no and x.deleted_flag = 0 and x.product_type like concat('%', #{criteria.productType}, '%')) or exists (select 1 from corporate_credit_drawdown x where x.customer_no_snapshot = c.customer_no and x.deleted_flag = 0 and x.product_type like concat('%', #{criteria.productType}, '%')) or exists (select 1 from corporate_risk_exposure x where x.customer_no = c.customer_no and x.deleted_flag = 0 and x.product_type like concat('%', #{criteria.productType}, '%')) )
and c.status = #{criteria.status}
and exists ( select 1 from corporate_debt_default x where x.customer_no = c.customer_no and x.deleted_flag = 0 and x.default_level = #{criteria.defaultLevel} )
and ( ifnull(c.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') or ifnull(l.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') )
and date(c.created_at) >= #{criteria.startDate}
and date(c.created_at) <= #{criteria.endDate}

from corporate_credit_limit l join corporate_customer c on c.customer_no = l.customer_no_snapshot left join corporate_rating r on r.active_customer_no = c.customer_no left join ( select related_limit_id as limit_id, count(*) as application_count, sum(apply_amount) as application_amount_total from corporate_credit_application where deleted_flag = 0 group by related_limit_id ) app on app.limit_id = l.id left join ( select limit_id, count(*) as contract_count, sum(contract_amount) as contract_amount_total, sum(available_draw_amount) as available_draw_amount_total from corporate_credit_contract where deleted_flag = 0 group by limit_id ) ct on ct.limit_id = l.id left join ( select limit_id, count(*) as drawdown_count, sum(actual_draw_amount) as actual_draw_amount_total, sum(outstanding_principal_amount) as outstanding_principal_amount_total from corporate_credit_drawdown where deleted_flag = 0 group by limit_id ) dr on dr.limit_id = l.id left join ( select dr.limit_id, count(ex.id) as exposure_count, sum(ex.ead_amount) as ead_amount_total, sum(ex.el_avg) as el_avg_total, max(ex.pd) as max_pd from corporate_credit_drawdown dr join corporate_risk_exposure ex on ex.drawdown_no = dr.drawdown_no and ex.deleted_flag = 0 where dr.deleted_flag = 0 group by dr.limit_id ) ex on ex.limit_id = l.id left join ( select dr.limit_id, count(ov.id) as overdue_count, max(ov.overdue_days) as max_overdue_days from corporate_credit_drawdown dr join corporate_credit_overdue ov on ov.debt_no = dr.debt_no and ov.deleted_flag = 0 where dr.deleted_flag = 0 group by dr.limit_id ) ov on ov.limit_id = l.id left join ( select dr.limit_id, count(dd.id) as debt_default_count, min(case dd.default_level when 'A' then 1 when 'B' then 2 when 'C' then 3 else 9 end) as highest_default_rank from corporate_credit_drawdown dr join corporate_debt_default dd on dd.debt_no = dr.debt_no and dd.deleted_flag = 0 where dr.deleted_flag = 0 group by dr.limit_id ) dd on dd.limit_id = l.id where l.deleted_flag = 0 and c.deleted_flag = 0
and ( l.limit_no like concat('%', #{criteria.keyword}, '%') or c.customer_no like concat('%', #{criteria.keyword}, '%') or c.customer_name like concat('%', #{criteria.keyword}, '%') or ifnull(l.approval_no, '') like concat('%', #{criteria.keyword}, '%') )
and c.customer_no like concat('%', #{criteria.customerNo}, '%')
and r.rating_level = #{criteria.ratingLevel}
and (l.risk_level = #{criteria.riskLevel} or c.risk_level = #{criteria.riskLevel})
and ( exists (select 1 from corporate_credit_application x where x.related_limit_id = l.id and x.deleted_flag = 0 and x.product_type like concat('%', #{criteria.productType}, '%')) or exists (select 1 from corporate_credit_contract x where x.limit_id = l.id and x.deleted_flag = 0 and x.product_type like concat('%', #{criteria.productType}, '%')) or exists (select 1 from corporate_credit_drawdown x where x.limit_id = l.id and x.deleted_flag = 0 and x.product_type like concat('%', #{criteria.productType}, '%')) )
and l.limit_status = #{criteria.status}
and exists ( select 1 from corporate_credit_drawdown x join corporate_debt_default y on y.debt_no = x.debt_no and y.deleted_flag = 0 where x.limit_id = l.id and x.deleted_flag = 0 and y.default_level = #{criteria.defaultLevel} )
and ( ifnull(l.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') or ifnull(c.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') )
and l.effective_date >= #{criteria.startDate}
and l.effective_date <= #{criteria.endDate}

from corporate_credit_drawdown dr join corporate_customer c on c.customer_no = dr.customer_no_snapshot left join corporate_credit_contract ct on ct.contract_no = dr.contract_no_snapshot and ct.deleted_flag = 0 left join corporate_rating r on r.active_customer_no = c.customer_no left join (
) ex on ex.drawdown_no = dr.drawdown_no left join ( select debt_no, count(*) as overdue_count, max(overdue_days) as max_overdue_days, sum(total_overdue_amount) as overdue_amount_total from corporate_credit_overdue where deleted_flag = 0 group by debt_no ) ov on ov.debt_no = dr.debt_no left join corporate_debt_default dd on dd.debt_no = dr.debt_no and dd.deleted_flag = 0 left join corporate_customer_default cd on cd.active_customer_no = c.customer_no left join ( select contract_no, count(*) as collateral_relation_count, sum(secured_amount) as total_secured_amount from corporate_credit_contract_collateral where deleted_flag = 0 and relation_status = 'ACTIVE' group by contract_no ) rel on rel.contract_no = dr.contract_no_snapshot where dr.deleted_flag = 0 and c.deleted_flag = 0
and ( dr.drawdown_no like concat('%', #{criteria.keyword}, '%') or ifnull(dr.debt_no, '') like concat('%', #{criteria.keyword}, '%') or c.customer_no like concat('%', #{criteria.keyword}, '%') or c.customer_name like concat('%', #{criteria.keyword}, '%') or ifnull(ct.contract_no, '') like concat('%', #{criteria.keyword}, '%') or ifnull(ex.exposure_no, '') like concat('%', #{criteria.keyword}, '%') or ifnull(dd.debt_default_no, '') like concat('%', #{criteria.keyword}, '%') )
and c.customer_no like concat('%', #{criteria.customerNo}, '%')
and (r.rating_level = #{criteria.ratingLevel} or ifnull(ex.rating_result, '') = #{criteria.ratingLevel})
and (dr.risk_level = #{criteria.riskLevel} or ifnull(ex.risk_level, '') = #{criteria.riskLevel} or c.risk_level = #{criteria.riskLevel})
and (dr.product_type like concat('%', #{criteria.productType}, '%') or ifnull(ex.product_type, '') like concat('%', #{criteria.productType}, '%'))
and (dr.drawdown_status = #{criteria.status} or ifnull(ex.exposure_status, '') = #{criteria.status})
and dd.default_level = #{criteria.defaultLevel}
and ( ifnull(dr.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') or ifnull(ct.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') or ifnull(c.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') )
and dr.drawdown_date >= #{criteria.startDate}
and dr.drawdown_date <= #{criteria.endDate}

from corporate_credit_overdue ov join corporate_customer c on c.customer_no = ov.customer_no left join corporate_rating r on r.active_customer_no = c.customer_no left join corporate_credit_drawdown dr on dr.drawdown_no = ov.drawdown_no and dr.deleted_flag = 0 left join corporate_credit_contract ct on ct.contract_no = ov.contract_no and ct.deleted_flag = 0 left join (
) ex on ex.debt_no = ov.debt_no left join corporate_debt_default dd on dd.debt_no = ov.debt_no and dd.deleted_flag = 0 left join corporate_customer_default cd on cd.active_customer_no = c.customer_no where ov.deleted_flag = 0 and c.deleted_flag = 0
and ( ov.overdue_no like concat('%', #{criteria.keyword}, '%') or c.customer_no like concat('%', #{criteria.keyword}, '%') or c.customer_name like concat('%', #{criteria.keyword}, '%') or ov.contract_no like concat('%', #{criteria.keyword}, '%') or ov.debt_no like concat('%', #{criteria.keyword}, '%') or ifnull(ov.drawdown_no, '') like concat('%', #{criteria.keyword}, '%') or ifnull(dd.debt_default_no, '') like concat('%', #{criteria.keyword}, '%') or ifnull(cd.customer_default_no, '') like concat('%', #{criteria.keyword}, '%') )
and c.customer_no like concat('%', #{criteria.customerNo}, '%')
and (r.rating_level = #{criteria.ratingLevel} or ifnull(dd.rating_result, '') = #{criteria.ratingLevel} or ifnull(ex.rating_result, '') = #{criteria.ratingLevel})
and (ov.risk_level = #{criteria.riskLevel} or ifnull(ex.risk_level, '') = #{criteria.riskLevel} or c.risk_level = #{criteria.riskLevel})
and (ov.product_type like concat('%', #{criteria.productType}, '%') or ifnull(dd.product_type, '') like concat('%', #{criteria.productType}, '%') or ifnull(ex.product_type, '') like concat('%', #{criteria.productType}, '%'))
and (ov.repayment_status = #{criteria.status} or ov.collection_status = #{criteria.status} or ifnull(dd.default_status, '') = #{criteria.status})
and dd.default_level = #{criteria.defaultLevel}
and ( ifnull(ov.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') or ifnull(ct.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') or ifnull(c.owner_org_name, '') like concat('%', #{criteria.ownerOrgName}, '%') )
and ov.overdue_date >= #{criteria.startDate}
and ov.overdue_date <= #{criteria.endDate}
